def test_determinant_8x8_fraction_exact():
    rng = random.Random(8)
    m = [[Fraction(rng.randint(-5, 5), rng.randint(1, 4)) for _ in range(8)] for _ in range(8)]
    result = determinant(m)
    assert type(result) is Fraction
    # Check against the defining property: det(M) * det(M^-1 path) is not needed;
    # instead verify multiplicativity det(AB) = det(A) det(B) on the same size.
    other = [[Fraction(rng.randint(-5, 5), 3) for _ in range(8)] for _ in range(8)]
    assert determinant(matmul(m, other)) == result * determinant(other)


def test_determinant_permutations_sign():
    for perm in itertools.permutations(range(4)):
        m = [[1 if j == perm[i] else 0 for j in range(4)] for i in range(4)]
        inversions = sum(
            1 for i in range(4) for j in range(i + 1, 4) if perm[i] > perm[j]
        )
        assert determinant(m) == (-1) ** inversions


